    W = len(grid[0])
    for r in range(H):
        for c in range(W):
            if grid[r][c] != background_color:
                non_bg_coords.append((r, c))

    if not non_bg_coords:
        return grid

    min_r, max_r = min(row for row, col in non_bg_coords), max(row for row, col in non_bg_coords)
    min_c, max_c = min(col for row, col in non_bg_coords), max(col for row, col in non_bg_coords)

    inner_r_min, inner_r_max = min_r + 1, max_r - 1
    inner_c_min, inner_c_max = min_c + 1, max_c - 1

    if inner_r_min > inner_r_max or inner_c_min > inner_c_max:
        return grid

    inner_h = inner_r_max - inner_r_min + 1
    inner_w = inner_c_max - inner_c_min + 1
