def transform(grid):
    background = grid[0][0]
    H, W = len(grid), len(grid[0])

    output = [row[:] for row in grid]

    # Find colored pixels inside the frame (not background color)
    colored = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != background:
                colored.append((r, c, grid[r][c]))

    # Find frame boundaries
    frame_min_r = min(r for r, c, v in colored)
    frame_max_r = max(r for r, c, v in colored)
    frame_min_c = min(c for r, c, v in colored)
    frame_max_c = max(c for r, c, v in colored)

    # Clear inside of frame
    for r in range(frame_min_r + 1, frame_max_r):
        for c in range(frame_min_c + 1, frame_max_c):
            output[r][c] = background

    # Move each pixel to corners (based on demo: 4 pixels -> 4 corners)
    # Top-left quadrant -> (0,0)
    # Top-right quadrant -> (0, W-1)
    # Bottom-left quadrant -> (H-1, 0)
    # Bottom-right quadrant -> (H-1, W-1)
    # Use vertical midpoint for row split, horizontal midpoint for column split
    mid_r = (frame_min_r + frame_max_r) // 2
    mid_c = (frame_min_c + frame_max_c) // 2

    for r, c, val in colored:
        if r <= mid_r and c <= mid_c:
            output[0][0] = val
        elif r <= mid_r and c > mid_c:
            output[0][W-1] = val
        elif r > mid_r and c <= mid_c:
            output[H-1][0] = val
        else:
            output[H-1][W-1] = val

    return output
